// GEN_FSH_FisherTransform.c  (GENERATED by analysis/harness/generator.py from the spec; edit the spec, not this file)
//
// PURPOSE:  Batch harness FSH. Feeds synthetic inputs through FisherCore (10 variants:
//           FR10, FR20, NCB [info], NCW [control], NCC [control], NCK [control], NCL [control], NC32 [control], NCS [control], NCT [control]) and writes the RAW outputs. It does NOT judge anything.
//           Python (analysis/harness/checker.py) measures and writes PASS/FAIL.
// PREREG:   analysis/harness/specs/FSH_ArticleFidelity.toml (this file)
// INPUTS:   Synthetic only, from the bar counter n: flat | level+amp*sin(2*pi*n/T), T=5,10,20,40,100 | ramp level+slope*n | rampdn level-slope*n
//           level=11/10 amp=1/100 slope=1/10000. (b, H1 run 1) Decimal literals are float32 in this Zorro
//           build and the PI macro is 3.14159, so every constant is built at run time from integers.
//           EUR/USD is used only as a bar clock; clock_close is exported for the checker's magnitude guard.
// OUTPUT:   Data/GEN_FSH_raw.csv  (3000 rows n=0..2999 + header; 376 columns; values printed with 15 decimals)
//           copies sc (level 11/10 amp 1/10), of (level 22/10 amp 1/100): every sine again with the transform's level/amp (sc/of ...), for variants with invariance.
// CALLS:    100 filter calls per bar, variant-major, unconditional, fixed order (gotchas 3.1).
// FEEDING:  every x[n], n=0..2999, reaches the filters exactly once; INITRUN and EXITRUN feed and write nothing.
// NO LOOKBACK GUARD: LookBack = 0, warmup bars are exported too; the checker requires n = 0..2999 contiguous.
// SOURCES:  expected values and tolerances are in the spec, each with an (a)/(b)/(c) label.
//           Pattern copied from strategies/tests/H1_SuperSmoother2Pole_Harness.c (b: H1 run 2 PASS).
// Y[] slots: variant-major; per call the outputs in the listed order (the last is the return value); see the call comments.

#include <default.c>
#include "../../indicators/ehlers/FisherTransform_Superseded.c"
#include "../../indicators/ehlers/FisherTransform.c"

#define FSH_RAW "Data/GEN_FSH_raw.csv"
#define FSH_MARK "Data/GEN_FSH_exit_marker.txt"
#define FSH_NBARS 3000

static int fsh_n = 0;
static int fsh_done = 0;
static int fsh_hdr = 0;
static int fsh_rows = 0;

// INFO variant (not a control, not in [detect]): [corrected_code] with source B's constants (a = b = 1/2, thr = cl = 9999/10000, log gain 1/4; Fish feedback 1/2 as both sources). Reported, never PASS/FAIL. (b) Its v1 reaches .9999 > .999, so its bound-v1 row is above the FR10 bound by 9e-4 (INFO).
var fsh_ncb(vars Price, int Len, var* pRaw, var* pV1, var* pRng, var* pTrig)
{
	vars ncb_V = series(0, 2);
	vars ncb_F = series(0, 2);
	var ncb_a = 1;    ncb_a = ncb_a/2;
	var ncb_b = 1;    ncb_b = ncb_b/2;
	var ncb_t = 9999; ncb_t = ncb_t/10000;
	var ncb_c = 9999; ncb_c = ncb_c/10000;
	var ncb_h = 1;    ncb_h = ncb_h/2;
	var ncb_k = 1;    ncb_k = ncb_k/4;
	var ncb_hi = MaxVal(Price, Len);
	var ncb_lo = MinVal(Price, Len);
	var ncb_rng = ncb_hi - ncb_lo;
	var ncb_raw = 0;
	if(ncb_rng > 0) {
		ncb_raw = Price[0] - ncb_lo;
		ncb_raw = ncb_raw/ncb_rng;
		ncb_raw = ncb_raw - ncb_h;
		ncb_raw = ncb_raw*2;
	}
	ncb_V[0] = ncb_a*ncb_raw + ncb_b*ncb_V[1];
	var ncb_nt = 0;   ncb_nt = ncb_nt - ncb_t;
	var ncb_nc = 0;   ncb_nc = ncb_nc - ncb_c;
	if(ncb_V[0] > ncb_t)  ncb_V[0] = ncb_c;
	if(ncb_V[0] < ncb_nt) ncb_V[0] = ncb_nc;
	var ncb_u = 1;
	var ncb_num = ncb_u + ncb_V[0];
	var ncb_den = ncb_u - ncb_V[0];
	ncb_F[0] = ncb_k*log(ncb_num/ncb_den) + ncb_h*ncb_F[1];
	*pRaw  = ncb_raw;
	*pV1   = ncb_V[0];
	*pRng  = ncb_rng;
	*pTrig = ncb_F[1];
	return ncb_F[0];
}

